const upsertPushAlertState = `-- name: UpsertPushAlertState :exec
INSERT INTO push_alert_state (subject, kind, level, alerted_level, alerted_at, below_since, updated_at)
VALUES ($1, $2, $3, $4, $5, $6, $7)
ON CONFLICT (subject) DO UPDATE
SET kind = EXCLUDED.kind,
    level = EXCLUDED.level,
    alerted_level = EXCLUDED.alerted_level,
    alerted_at = EXCLUDED.alerted_at,
    below_since = EXCLUDED.below_since,
    updated_at = EXCLUDED.updated_at
`

type UpsertPushAlertStateParams struct {
	Subject      string     `json:"subject"`
	Kind         string     `json:"kind"`
	Level        int16      `json:"level"`
	AlertedLevel int16      `json:"alerted_level"`
	AlertedAt    *time.Time `json:"alerted_at"`
	BelowSince   *time.Time `json:"below_since"`
	UpdatedAt    time.Time  `json:"updated_at"`
}

func (q *Queries) UpsertPushAlertState(ctx context.Context, arg UpsertPushAlertStateParams) error {
	_, err := q.db.Exec(ctx, upsertPushAlertState,
		arg.Subject,
		arg.Kind,
		arg.Level,
		arg.AlertedLevel,
		arg.AlertedAt,
		arg.BelowSince,
		arg.UpdatedAt,
	)
	return err
}
